function MovieList() {

    const movies = [
        {
        title: 'Project Hail Mary',
        genre: 'Sci-Fi',
        releaseYear: '2026'
    },

    {
        title: 'One Piece: Film Red',
        genre: 'Anime',
        releaseYear: '2022'
    },

    {
        title: 'La La Land',
        genre: 'Musical',
        releaseYear: '2016'
    }

]

    return (
        <h1>Movie List</h1>
    );
}

export default MovieList;
